#include <vector>

int drop_small(std::vector<int>& sizes, int min_size) {
    int removed = 0;
    for (auto it = sizes.begin(); it != sizes.end(); ) {
        if (*it < min_size) {
            it = sizes.erase(it);
            ++removed;
        } else {
            ++it;
        }
    }
    return removed;
}

