int drop_small(std::vector<int>& sizes, int min_size) {
    int removed = 0;
    for (std::size_t i = 0; i < sizes.size(); ++i) {
        if (sizes[i] < min_size) {
            sizes.erase(sizes.begin() + i);
            ++removed;
        }
    }
    return removed;
}

